class SummaryRanges {
    map<int, int> intervals; // start -> end
public:
    SummaryRanges() {}

    void addNum(int value) {
        auto it = intervals.lower_bound(value);
        int leftEnd = -2;
        auto leftIt = intervals.end();
        if (it != intervals.begin()) {
            leftIt = prev(it);
            leftEnd = leftIt->second;
        }
        // Already covered by the left interval?
        if (leftEnd >= value) return;
        // Already the start of an existing interval?
        if (it != intervals.end() && it->first == value) return;

        bool mergeLeft  = (leftEnd == value - 1);
        bool mergeRight = (it != intervals.end() && it->first == value + 1);

        int newStart = value, newEnd = value;
        if (mergeLeft)  newStart = leftIt->first;
        if (mergeRight) newEnd   = it->second;

        if (mergeRight) intervals.erase(it);
        if (mergeLeft)  intervals.erase(leftIt);
        intervals[newStart] = newEnd;
    }

    vector<vector<int>> getIntervals() {
        vector<vector<int>> res;
        for (auto& [s, e] : intervals) res.push_back({s, e});
        return res;
    }
};
